const d = $json.body ?? $json;
const alerts = Array.isArray(d.alerts) ? d.alerts.filter(Boolean) : [];
const fallbackAlert = (d.alert_triggered || d.alert_reason || d.alert_severity)
  ? [{
      type: d.alert_type ?? 'ALERT',
      severity: d.alert_severity ?? 'warning',
      message: d.alert_reason ?? 'Queue alert',
      value: d.estimated_wait_sec ?? d.metrics?.wait_time_seconds ?? null,
      threshold: null,
    }]
  : [];
const effectiveAlerts = alerts.length > 0 ? alerts : fallbackAlert;
const primaryAlert = effectiveAlerts[0] ?? null;
const alertType = primaryAlert?.type ?? 'ALERT';
const severity = primaryAlert?.severity ?? d.alert_severity ?? 'warning';
const zoneId = d.zone_id ?? d.feed_id ?? 'unknown';
const cooldownSeconds = 120;
const now = Date.now();
const staticData = getWorkflowStaticData('global');
staticData.alertCooldowns ??= {};
const cooldownKey = `${zoneId}:${alertType}:${severity}`;
const lastSentAt = staticData.alertCooldowns[cooldownKey] ?? 0;
const shouldSendTelegram = !lastSentAt || (now - lastSentAt) >= cooldownSeconds * 1000;
const cooldownRemainingSeconds = shouldSendTelegram ? 0 : Math.max(0, Math.ceil((cooldownSeconds * 1000 - (now - lastSentAt)) / 1000));
if (shouldSendTelegram) {
  staticData.alertCooldowns[cooldownKey] = now;
}
return [{ json: { ...d, alerts: effectiveAlerts, primary_alert: primaryAlert, alert_type: alertType, alert_severity: severity, send_telegram: shouldSendTelegram, cooldown_seconds: cooldownSeconds, cooldown_remaining_seconds: cooldownRemainingSeconds, cooldown_key: cooldownKey } }];

const d = $json.body ?? $json;
const escapeMarkdown = (value) => String(value ?? 'n/a').replace(/([_*\[\]()`])/g, '\$1');
const alert = d.primary_alert ?? (Array.isArray(d.alerts) && d.alerts.length > 0 ? d.alerts[0] : null) ?? { type: d.alert_type ?? 'ALERT', severity: d.alert_severity ?? 'warning', message: d.alert_reason ?? 'Queue alert', value: d.estimated_wait_sec ?? d.metrics?.wait_time_seconds ?? null, threshold: null };
const zone = d.zone_id || d.feed_id || 'unknown';
const prefix = String(alert.severity ?? d.alert_severity ?? 'warning').toLowerCase() === 'critical' ? '🚨 *CRITICAL ALERT*' : '⚠️ *WARNING*';
const reason = alert.message || d.alert_reason || 'Queue length warning';
const severity = alert.severity || d.alert_severity || 'warning';
const people = d.people_in_zone ?? d.metrics?.people_in_zone ?? 'n/a';
const waitTime = alert.value ?? d.estimated_wait_sec ?? d.metrics?.wait_time_seconds ?? 'n/a';
const waitCi = d.wait_time_lower != null && d.wait_time_upper != null
  ? `${d.wait_time_lower} - ${d.wait_time_upper}`
  : (d.uncertainty?.wait_time_ci ? `${d.uncertainty.wait_time_ci[0]} - ${d.uncertainty.wait_time_ci[1]}` : 'n/a');
const alertSummary = Array.isArray(d.alerts) && d.alerts.length > 1
  ? '\n' + `🧾 *Alerts:* ${d.alerts.map((item) => `${escapeMarkdown(item.type)} (${escapeMarkdown(item.severity)})`).join(', ')}`
  : '';
const text = `${prefix} — ${escapeMarkdown(zone)}

` +
  `📍 *Alert:* ${escapeMarkdown(reason)}
` +
  `📊 *Severity:* ${escapeMarkdown(severity)}
` +
  `👥 *In Queue:* ${people} people
` +
  `⏱ *Wait Time:* ${waitTime}s [CI: ${waitCi}]${alertSummary}
` +
  `📈 *Uncertainty:* ${escapeMarkdown(d.uncertainty_level ?? d.uncertainty?.level ?? 'n/a')}
` +
  `🕐 ${d.timestamp ?? new Date().toISOString()}`;
return [{ json: { message: text, feed_id: d.feed_id || null, zone_id: d.zone_id || null, alert_reason: reason, alert_severity: severity, alerts_count: Array.isArray(d.alerts) ? d.alerts.length : 0 } }];
